const escapeHtml=(s='')=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))
const statusName=s=>{const x=String(s||'').toLowerCase();return x==='active'?'Active':(x==='reveal'||x==='locked')?'Reveal':(x==='complete'||x==='completed')?'Complete':'Draft'}
const fmtTime=ms=>{if(ms==null)return '—';const t=Math.floor(ms/1000),milli=ms%1000,h=Math.floor(t/3600),m=Math.floor((t%3600)/60),s=t%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(milli).padStart(3,'0')}`:`${m}:${String(s).padStart(2,'0')}.${String(milli).padStart(3,'0')}`}
function parseTime(v){const p=v.trim().split(':');let h=0,m=0,s=0;if(p.length===2){m=Number(p[0]);s=Number(p[1])}else if(p.length===3){h=Number(p[0]);m=Number(p[1]);s=Number(p[2])}else throw Error('Use M:SS.mmm or H:MM:SS.mmm');if(![h,m,s].every(Number.isFinite)||h<0||m<0||s<0||s>=60)throw Error('Invalid time');return Math.round((h*3600+m*60+s)*1000)}
let authWork=Promise.resolve(), countdownHandle=null
function withTimeout(promise,ms,label){let timer;const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(`${label} timed out after ${Math.round(ms/1000)} seconds.`)),ms)});return Promise.race([promise,timeout]).finally(()=>clearTimeout(timer))}
async function loadSignedInApp(){splash('Loading Legends…');try{await withTimeout(loadProfile(),12000,'Runner profile');await withTimeout(loadAll(),18000,'Legends data');render()}catch(err){console.error(err);app.innerHTML=`<div class="loginPage"><div class="errorBox"><h2>LEGENDS WEB ERROR</h2><p>${escapeHtml(err.message||String(err))}</p><button class="primary" id="retryLoad">TRY AGAIN</button><button class="ghost" id="errorLogout">LOG OUT</button></div></div>`;document.querySelector('#retryLoad').onclick=loadSignedInApp;document.querySelector('#errorLogout').onclick=()=>supabase.auth.signOut()}}
async function boot(){supabase.auth.onAuthStateChange((event,session)=>{state.session=session;authWork=authWork.then(async()=>{await new Promise(r=>setTimeout(r,0));if(event==='PASSWORD_RECOVERY'&&session){const pw=prompt('Enter your new Legends password (6+ characters)');if(pw&&pw.length>=6){const {error}=await supabase.auth.updateUser({password:pw});alert(error?error.message:'Password updated.')} }if(session)await loadSignedInApp();else{state.profile=null;render()}}).catch(console.error)});const {data,error}=await withTimeout(supabase.auth.getSession(),10000,'Session check');if(error)throw error;state.session=data.session;if(state.session)await loadSignedInApp();else render()}
async function loadProfile(){const {data,error}=await supabase.from('profiles').select('id,username,role,disabled').eq('id',state.session.user.id).maybeSingle();if(error)throw error;state.profile=data}
async function loadAll(){
  const {data:chs,error:ce}=await supabase.from('challenges').select('id,name,status,created_at,revealed_at,started_at,ends_at,completed_at').order('id',{ascending:false});
  if(ce)throw ce;
  state.challenges=chs||[];
  state.challenge=state.challenges.find(c=>['Active','Reveal','Draft'].includes(statusName(c.status)))||state.challenges[0]||null;
  const {data:allProfiles,error:pe}=await supabase.from('profiles').select('id,username,role,disabled').order('username');
  if(pe)throw pe;
  state.profiles=allProfiles||[];
  if(!state.challenge){state.games=[];state.submissions=[];state.members=[];state.champions=[]}
  else{
    const cid=state.challenge.id;
    const [g,s,m,cp]=await Promise.all([
      supabase.from('challenge_games').select('*').eq('challenge_id',cid).order('slot'),
      supabase.from('submissions').select('id,challenge_id,challenge_game_id,user_id,time_ms,proof_url,submitted_at').eq('challenge_id',cid),
      supabase.from('challenge_members').select('challenge_id,user_id,joined_at').eq('challenge_id',cid),
      supabase.from('champions').select('challenge_id,user_id,total_time_ms,awarded_at').eq('challenge_id',cid)
    ]);
    const err=[g.error,s.error,m.error,cp.error].find(Boolean);if(err)throw err;
    state.games=g.data||[];state.submissions=s.data||[];state.members=m.data||[];state.champions=cp.data||[];
  }
  const gotm=await supabase.from('game_of_the_month').select('*').eq('active',true).order('month_key',{ascending:false}).limit(1).maybeSingle();
  state.monthlyTableMissing=!!gotm.error;
  state.monthly=gotm.error?null:gotm.data;
  state.monthlySubmissions=[];state.monthlySetupMissing=false;
  if(state.monthly){
    const ms=await supabase.from('game_of_the_month_submissions').select('id,game_of_the_month_id,user_id,time_ms,proof_url,submitted_at').eq('game_of_the_month_id',state.monthly.id);
    if(ms.error)state.monthlySetupMissing=true;else state.monthlySubmissions=ms.data||[];
  }
}
function standings(){const pmap=new Map(state.profiles.map(p=>[p.id,p.username])),ids=new Set([...state.members.map(m=>m.user_id),...state.submissions.map(s=>s.user_id)]),rows=[];for(const uid of ids){const times=new Map();for(const g of state.games){const vals=state.submissions.filter(s=>s.user_id===uid&&s.challenge_game_id===g.id).map(s=>s.time_ms);if(vals.length)times.set(g.id,Math.min(...vals))}const done=times.size,total=state.games.length&&done===state.games.length?[...times.values()].reduce((a,b)=>a+b,0):null;rows.push({uid,username:pmap.get(uid)||'Runner',done,total,times})}return rows.sort((a,b)=>a.total!=null&&b.total!=null?a.total-b.total:a.total!=null?-1:b.total!=null?1:b.done-a.done||a.username.localeCompare(b.username))}
function render(){if(countdownHandle){clearInterval(countdownHandle);countdownHandle=null}if(!state.session)return renderLogin();if(!state.profile)return splash('Loading runner profile…');if(state.profile.disabled)return splash('This Legends account is disabled.');const admin=state.profile.role==='Admin';app.innerHTML=`<div class="appShell"><aside class="sidebar"><img src="/legends-logo.png" class="sideLogo"><nav>${navButton('challenge','◆','Active Challenge')}${navButton('overall','▥','Overall Leaderboard')}${navButton('games','▦','Game Leaderboards')}${navButton('monthly','★','Game of the Month')}${navButton('champions','♛','Champions')}${navButton('profile','●','Runner Profile')}${navButton('history','◷','Challenge History')}${admin?navButton('creator','＋','Challenge Creator'):''}${admin?navButton('reveal','◇','Reveal Control'):''}${admin?navButton('admin','⚙','Admin'):''}</nav><div class="signedIn">SIGNED IN AS<br><b>${escapeHtml(state.profile.username)}</b></div></aside><main class="main"><header class="topbar"><div><span class="eyebrow">LEGENDS OF RETRO</span> <b>${escapeHtml(state.profile.role).toUpperCase()}</b></div><button class="ghost" id="logout">LOG OUT</button></header><div id="page"></div></main></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});document.querySelector('#logout').onclick=()=>supabase.auth.signOut();const page=document.querySelector('#page');if(state.tab==='challenge')page.innerHTML=challengePage();if(state.tab==='overall')page.innerHTML=overallPage();if(state.tab==='games')page.innerHTML=gamesPage();if(state.tab==='monthly')page.innerHTML=monthlyPage();if(state.tab==='champions')page.innerHTML=championsPage();if(state.tab==='profile')page.innerHTML=profilePage();if(state.tab==='history')page.innerHTML=historyPage();if(state.tab==='creator'&&admin)page.innerHTML=creatorPage();if(state.tab==='reveal'&&admin)page.innerHTML=revealPage();if(state.tab==='admin'&&admin)page.innerHTML=adminPage();wirePage()}
