  app.innerHTML=`<div class="loginPage"><div class="loginCard"><img src="/legends-logo.png" class="loginLogo"><h1>ENTER LEGENDS</h1><p>Log in or create a free Runner account.</p><div class="authTabs"><button class="primary" id="showLogin">LOG IN</button><button class="outline" id="showSignup">CREATE RUNNER ACCOUNT</button></div><div id="authPanel"></div></div></div>`
  const panel=document.querySelector('#authPanel')
  const login=()=>{panel.innerHTML=`<form id="loginForm" class="formStack"><input type="email" id="email" placeholder="Email" required><input type="password" id="password" placeholder="Password" required><button class="primary">LOG IN</button><button type="button" class="linkButton" id="forgotPassword">FORGOT PASSWORD?</button><div id="loginMsg" class="error"></div></form>`;document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('.primary');btn.disabled=true;btn.textContent='SIGNING IN…';const {error}=await supabase.auth.signInWithPassword({email:document.querySelector('#email').value.trim(),password:document.querySelector('#password').value});if(error){document.querySelector('#loginMsg').textContent=error.message;btn.disabled=false;btn.textContent='LOG IN'}};document.querySelector('#forgotPassword').onclick=forgot}
  const signup=()=>{panel.innerHTML=`<form id="signupForm" class="formStack"><input type="text" id="runnerName" placeholder="Runner name" maxlength="40" required><input type="email" id="signupEmail" placeholder="Email" required><input type="password" id="signupPassword" placeholder="Password (6+ characters)" minlength="6" required><input type="password" id="signupConfirm" placeholder="Confirm password" minlength="6" required><button class="primary">CREATE RUNNER ACCOUNT</button><div class="muted">New public accounts are always created as Runner.</div><div id="signupMsg" class="error"></div></form>`;document.querySelector('#signupForm').onsubmit=async e=>{e.preventDefault();const msg=document.querySelector('#signupMsg'),btn=e.currentTarget.querySelector('.primary'),username=document.querySelector('#runnerName').value.trim(),email=document.querySelector('#signupEmail').value.trim(),password=document.querySelector('#signupPassword').value,confirm=document.querySelector('#signupConfirm').value;msg.className='error';msg.textContent='';if(username.length<2){msg.textContent='Runner name must be at least 2 characters.';return}if(password!==confirm){msg.textContent='Passwords do not match.';return}btn.disabled=true;btn.textContent='CREATING…';try{const {data,error}=await supabase.auth.signUp({email,password,options:{data:{username,role:'Runner'},emailRedirectTo:location.origin}});if(error)throw error;if(!data.user)throw Error('Account was not created.');const r=await fetch('/api/register-profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:data.user.id,email,username})});const raw=await r.text();let out={};try{out=raw?JSON.parse(raw):{}}catch{}if(!r.ok)throw Error(out.error||raw||`Runner profile could not be created (HTTP ${r.status}).`);msg.className='successText';msg.textContent=data.session?'ACCOUNT CREATED — signing you in…':'ACCOUNT CREATED — check your email to confirm it, then log in.';if(!data.session){btn.disabled=false;btn.textContent='CREATE RUNNER ACCOUNT'}}catch(err){msg.textContent=err.message||String(err);btn.disabled=false;btn.textContent='CREATE RUNNER ACCOUNT'}}}
  const forgot=()=>{panel.innerHTML=`<form id="forgotForm" class="formStack"><h2>RESET PASSWORD</h2><p class="muted">Enter your account email and we'll send a reset link.</p><input type="email" id="resetEmail" placeholder="Email" required><button class="primary">SEND RESET LINK</button><button type="button" class="ghost" id="backLogin">BACK TO LOGIN</button><div id="resetMsg" class="error"></div></form>`;document.querySelector('#backLogin').onclick=login;document.querySelector('#forgotForm').onsubmit=async e=>{e.preventDefault();const msg=document.querySelector('#resetMsg'),btn=e.currentTarget.querySelector('.primary');btn.disabled=true;btn.textContent='SENDING…';const {error}=await supabase.auth.resetPasswordForEmail(document.querySelector('#resetEmail').value.trim(),{redirectTo:location.origin});if(error){msg.textContent=error.message;btn.disabled=false;btn.textContent='SEND RESET LINK'}else{msg.className='successText';msg.textContent='RESET EMAIL SENT. Check your inbox.';btn.disabled=false;btn.textContent='SEND RESET LINK'}}}
  document.querySelector('#showLogin').onclick=login;document.querySelector('#showSignup').onclick=signup;login()
